(function execute(inputs, outputs) {
try {
    var getInboundRec = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound')
    getInboundRec.get(inputs.widgetInboundRecord);

    var messageID = getInboundRec.message_id.toString() ? getInboundRec.message_id.toString() : "";
    var eventType = getInboundRec.event_type.toString() ? getInboundRec.event_type.toString() : "";
    var eventsource = getInboundRec.source.toString() ? getInboundRec.source.toString() : "";
    var objType = getInboundRec.object_type.toString() ? getInboundRec.object_type.toString() : "";
    var objTypeID = getInboundRec.object_id_type.toString() ? getInboundRec.object_id_type.toString() : "";
    var eventStatus = getInboundRec.event_status.toString() ? getInboundRec.event_status.toString() : "";
    var payload = getInboundRec.payload ? getInboundRec.payload : "";

    var getPayload = JSON.parse(payload);
    var id = getPayload.PAYLOAD.id;
    var resourceType = getPayload.PAYLOAD.meta.resourceType.toString() ? getPayload.PAYLOAD.meta.resourceType.toString() : "";
    var metaLocation = getPayload.PAYLOAD.meta.location.toString() ? getPayload.PAYLOAD.meta.location.toString() : "";
    var bubbleID = getPayload.PAYLOAD.bubbleId.toString() ? getPayload.PAYLOAD.bubbleId.toString() : "";
    var participantID = getPayload.PAYLOAD.participantId.toString() ? getPayload.PAYLOAD.participantId.toString() : "";
    var messageData = getPayload.PAYLOAD.message.toString() ? getPayload.PAYLOAD.message.toString() : "";
    var sideJournal = getPayload.PAYLOAD.sideJournal.toString() ? getPayload.PAYLOAD.sideJournal.toString() : "";
    var unRead = getPayload.PAYLOAD.unread.toString() ? getPayload.PAYLOAD.unread.toString() : "";
    var systemMessage = getPayload.PAYLOAD.systemMessage.toString() ? getPayload.PAYLOAD.systemMessage.toString() : "";

    //settingOutputs
    outputs.messageid = messageID;
    outputs.eventtype = eventType;
    outputs.eventsource = eventsource;
    outputs.objtype = objType;
    outputs.objtypeid = objTypeID;
    outputs.eventstatus = eventStatus;
    outputs.id = id;
    outputs.resourcetype = resourceType;
    outputs.metalocation = metaLocation;
    outputs.bubbleid = bubbleID;
    outputs.participantid = participantID;
    outputs.message = messageData;
    outputs.sidejournal = sideJournal;
    outputs.unread = unRead;
    outputs.systemmessage = systemMessage;
    //settingOutputs

} catch (ex) {
    gs.info('Error From MSS Taskize Bubble Create/Update ' + ex);
}




})(inputs, outputs);
